update pages set contenu = '{"sections":[]}'::jsonb where path = '/implantations/nantes/rennes/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"heros","h1":"Maintenance industrielle à Rennes et en Ille-et-Vilaine","mecanisme":"Le bassin rennais est plus industriel qu''il n''en a l''air. L''agroalimentaire breton, les équipementiers automobiles de Chartres-de-Bretagne, les sites de production électronique portés par le numérique. Nos équipes y interviennent avec des techniciens qui se déplacent sur vos sites : nous n''avons ni agence ni hub de techniciens à Rennes.","cta":"Faire chiffrer ma maintenance à Rennes","telephone":"04 78 33 72 05","phraseDelai":"Un chargé d''affaires vous rappelle dans l''heure, du lundi au vendredi de 8h00 à 18h30. L''astreinte 24/24 et 7/7 existe en option de contrat."},{"type":"chiffres","chiffres":[{"valeur":"+ 80","libelle":"clients réguliers parmi plus de 120 clients industriels en France"},{"valeur":"10 %","libelle":"des candidats retenus, entretien technique et comportemental, résultats partagés"},{"valeur":"2 à 3 semaines","libelle":"délai de prise de poste d''un technicien intégré à votre équipe"}]},{"type":"probleme","punchline":"Tapez « technicien de maintenance Rennes » : vous tomberez sur des centaines d''annonces ouvertes, pas sur un candidat. Le vrai sujet du bassin n''est pas la panne, c''est l''absence de bras pour la traiter.","puces":[{"accroche":"Recruter prend des trimestres.","texte":"Entre l''annonce, les entretiens, les contre-offres et le préavis, votre préventif glisse et le correctif explose."},{"accroche":"Un seul technicien porte tout le site.","texte":"Le jour où il est absent, l''usine devient aveugle sur ses propres équipements."},{"accroche":"L''agroalimentaire ne pardonne pas l''arrêt.","texte":"Conditionnement, froid industriel, lavage intensif : la panne se paie en produit perdu, pas en heures."},{"accroche":"Les cadences automobiles ne laissent pas de marge.","texte":"Traçabilité, conformité, séries tendues : chaque minute d''arrêt remonte jusqu''au donneur d''ordre."},{"accroche":"Les sites d''énergie et d''utilités sont dispersés.","texte":"Stations et réseaux d''Ille-et-Vilaine se maintiennent sans immobiliser le service."}]},{"type":"offre","lignes":[{"prestation":{"accroche":"Technicien intégré à votre équipe","texte":"en [sous-traitance maintenance](/offres/residence/), encadré par un référent Migen."},"benefice":"Le poste vacant est tenu, sans embauche à porter ni recrutement à mener."},{"prestation":{"accroche":"Préventif et curatif en agroalimentaire","texte":"lignes de conditionnement, froid industriel, zones lavées."},"benefice":"La cadence tient, et l''hygiène ne se négocie pas contre du temps gagné."},{"prestation":{"accroche":"Électromécanique traitée par un seul intervenant","texte":"le couple mécanique et électrique, sans renvoi de responsabilité."},"benefice":"Un diagnostic, un responsable, une réparation. Pas trois prestataires qui se regardent."},{"prestation":{"accroche":"Automatisme et supervision","texte":"automates SIEMENS et Schneider, variation de vitesse, reprise de programmes sans documentation."},"benefice":"Une installation muette redevient pilotable par vos propres équipes."},{"prestation":{"accroche":"Convoyage et tri logistiques","texte":"du nord de l''agglomération et de Saint-Jacques-de-la-Lande."},"benefice":"Le flux repart avant la vague suivante, pas le lendemain matin."},{"prestation":{"accroche":"Robotique ABB et Fanuc","texte":"reprise de trajectoires, changements d''outillage, remise en cycle après incident."},"benefice":"La cellule reprend sans attendre le passage de l''intégrateur."},{"prestation":{"accroche":"Astreinte 24/24 et 7/7 en option","texte":"une alerte, un humain, une intervention organisée."},"benefice":"La nuit du dimanche ne décide plus de votre lundi."}],"prose":[{"texte":"Chaque passage alimente votre GMAO : historique, pièces, préconisations. Pour une panne isolée, le [dépannage industriel](/offres/depannage-industriel/) reste le format le plus simple pour nous juger sur pièces."}]},{"type":"deroule","etapes":[{"titre":"Votre appel","texte":"machine, symptôme, contexte de production. Cinq minutes suffisent pour poser le premier diagnostic."},{"titre":"Le rappel dans l''heure","texte":"aux horaires ouvrés. C''est le seul engagement de délai que nous signons, parce que c''est le seul que nous tenons à chaque fois."},{"titre":"La qualification","texte":"compétences requises, habilitations, expérience sur votre type d''équipement. Aucun envoi à l''aveugle."},{"titre":"L''intervention","texte":"technicien briefé et outillé, diagnostic, réparation jusqu''à la remise en service."},{"titre":"Le compte rendu","texte":"cause, actions, mesures, points à surveiller, versés dans votre GMAO."},{"titre":"Le bilan","texte":"si les arrêts reviennent, nous remontons à la cause racine et proposons le plan qui l''élimine."}]},{"type":"garanties","puces":[{"accroche":"Le bon métier, pas le premier disponible","texte":"un automaticien pour votre ligne, un électromécanicien pour votre moteur. La proximité utile est celle de la compétence."},{"accroche":"Une évaluation partagée avant l''arrivée","texte":"entretien technique et comportemental, 10 % des candidats retenus, résultats transmis. Vous savez qui entre sur votre site."},{"accroche":"La confidentialité tenue","texte":"vos données, vos consignes et vos process restent chez vous. Ce qui se voit chez un client reste chez ce client."}]},{"type":"cta","question":"Besoin de tenir un poste maintenance sans lancer un recrutement de plus ?","bouton":"Faire chiffrer ma maintenance à Rennes","rappel":"Ou appelez le 04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30. Rappel dans l''heure."}]'::jsonb) where path = '/implantations/nantes/rennes/';
update pages set contenu = jsonb_set(contenu, '{sections}', (contenu->'sections') || '[{"type":"preuves","preuves":[{"titre":"Des techniciens intégrés au quotidien des équipes de maintenance d''un équipementier automobile","texte":", sur les installations critiques, depuis 2025","lienLibelle":"Étude de cas JTEKT : maintenance des installations","lienHref":"/preuves/jtekt/"},{"titre":"Un technicien de maintenance dédié au maintien d''un parc machines","texte":", en présence continue et en coordination avec les équipes du site","lienLibelle":"Étude de cas AUTOLIV : maintien d''un site","lienHref":"/preuves/autoliv/"},{"titre":"Deux techniciens en 3x8 sur les lignes liquides et le conditionnement poudre","texte":"d''un site de nutrition infantile","lienLibelle":"Étude de cas DANONE : lignes de production","lienHref":"/preuves/danone-lignes-de-production/"},{"titre":"Un responsable maintenance intégré sur site pour piloter le service","texte":"pendant une intensification de production et une transition d''équipe","lienLibelle":"Étude de cas ERIKS","lienHref":"/preuves/eriks/"},{"titre":"Deux techniciens en poste permanent sur les convoyeurs, trieurs et lignes de packaging","texte":"d''un transporteur, en maintenance curative","lienLibelle":"Étude de cas GLS : maintenance curative","lienHref":"/preuves/gls-maintenance-curative/"}]},{"type":"objections","questions":[{"question":"D''où viennent les techniciens qui interviennent à Rennes ?","reponse":"Soyons clairs : nous n''avons ni agence ni hub de techniciens à Rennes. Le technicien est choisi selon la spécialité, automatisme, électromécanique, hydraulique, robotique, et il se déplace sur votre site. Le critère est la réponse adaptée à votre équipement, pas la seule distance. Chaque mission est préparée avant l''arrivée."},{"question":"Couvrez-vous Saint-Malo, Vitré, Fougères ou Redon ?","reponse":"Oui, ainsi que Chartres-de-Bretagne et toute l''Ille-et-Vilaine. Les départements voisins s''appuient sur la même organisation. Précisez votre commune au premier appel, nous confirmons immédiatement."},{"question":"Intervenez-vous en urgence la nuit ou le week-end ?","reponse":"Oui, dès lors que l''astreinte 24/24 et 7/7 figure à votre contrat. Aux horaires ouvrés, chaque demande obtient son rappel dans l''heure. Aucun délai chiffré n''est promis : nous organisons la remise en route, nous ne vendons pas une promesse commerciale."},{"question":"Travaillez-vous avec les PME et les ateliers, ou seulement les grands sites ?","reponse":"Les deux. Réparer une machine d''atelier mérite le même sérieux qu''entretenir une ligne automobile. Devis clair, technicien adapté, compte rendu écrit, quelle que soit la taille du parc."},{"question":"Proposez-vous des contrats de maintenance préventive ?","reponse":"Oui, avec le contrat [Zéro arrêt](/offres/zero-arret/) et ses trois niveaux de couverture. Travaux planifiés, postes critiques suivis, priorité en cas de panne, astreinte en option, indicateurs présentés à chaque bilan. À partir de sur devis, engagement type 6 mois renouvelable, après un état des lieux gratuit."},{"question":"Que faites-vous que notre prestataire actuel ne fait pas ?","reponse":"Nous écrivons. Compte rendu à chaque passage, historique tenu, cause racine cherchée quand la panne revient. Si un contrat vous lie déjà, commencez par un périmètre d''essai et laissez les chiffres trancher."}]},{"type":"ctaFinal","question":"Besoin d''arrêter de dépendre d''un seul technicien sur votre site ?","bouton":"Faire chiffrer ma maintenance à Rennes","rappel":"ou appelez le 04 78 33 72 05, rappel dans l''heure aux horaires ouvrés."}]'::jsonb) where path = '/implantations/nantes/rennes/';
